/* Team permissions, like Shopify's staff permissions (round 40, run after part 135): each person on a store's team gets their own list of what they may do, in a new column `store_team_members.permissions` (text[], from website, onepage, creator_pages, products, orders, customers, marketing, community, analytics, settings, team, payouts_billing), chosen in Settings > Team from a preset (Full access, Content editor, Support) or ticked one by one, and changed there later. Everyone already on a team keeps exactly what they could use before: a Manager gets orders, Staff (never open to invite) gets nothing; the old role column stays as it is. A row the app writes without the column reads as its role, so nothing breaks while an older server is still running. The table stays server only: row level security on, no policy, nothing granted to anon or signed in users; every page and route checks the member's permissions on the server on each request (lib/team/server requireTeamPermission). Until it runs, Settings > Team can only give Orders and says permissions are not set up for anything else. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.store_team_members') IS NULL THEN RAISE NOTICE 'part 320: store_team_members is not here yet; run part 135 first, then this again.'; RETURN; END IF; ALTER TABLE public.store_team_members ADD COLUMN IF NOT EXISTS permissions text[]; UPDATE public.store_team_members SET permissions = CASE WHEN role = 'manager' THEN ARRAY['orders']::text[] ELSE '{}'::text[] END WHERE permissions IS NULL; IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'store_team_members_permissions_check' AND conrelid = 'public.store_team_members'::regclass) THEN ALTER TABLE public.store_team_members ADD CONSTRAINT store_team_members_permissions_check CHECK (permissions IS NULL OR (permissions <@ ARRAY['website', 'onepage', 'creator_pages', 'products', 'orders', 'customers', 'marketing', 'community', 'analytics', 'settings', 'team', 'payouts_billing']::text[] AND cardinality(permissions) <= 12)); END IF; COMMENT ON COLUMN public.store_team_members.permissions IS 'What this member may do in the store (lib/team/permissions.ts). NULL: read as the role (manager: orders).'; ALTER TABLE public.store_team_members ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.store_team_members FROM PUBLIC, anon, authenticated; GRANT SELECT, INSERT, UPDATE, DELETE ON public.store_team_members TO service_role; END $do$;
notify pgrst, 'reload schema';
